// CaseComplexity page component
import React, { useState } from "react";
import "../styles/complexity.css";

function CaseComplexityChecker() {

  const [details, setDetails] = useState("");
  const [result, setResult] = useState("");

  const checkComplexity = () => {

    if (details.length < 50) {
      setResult("Low Complexity Case");
    }
    else if (details.length < 150) {
      setResult("Medium Complexity Case");
    }
    else {
      setResult("High Complexity Case");
    }

  };

  return (
    <div className="complexity-container">

      <h1>Case Complexity Checker</h1>

      <div className="complexity-form">

        <label>Describe Your Case</label>

        <textarea
          placeholder="Write details about your legal case..."
          value={details}
          onChange={(e) => setDetails(e.target.value)}
        />

        <button onClick={checkComplexity}>
          Check Complexity
        </button>

        {result && (
          <h2 className="result">
            {result}
          </h2>
        )}

      </div>

    </div>
  );
}

export default CaseComplexityChecker;
